INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (106511, "こうして遠出するのもいいもんだ。\n道中で強い魔物とかが出てくれば、\n面白いケンカもできそうだしさ。", 1, 11, 0, 20172, 1, 1201720005, 10, 0, 0);
