INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("vo_travel_talk", "vo_travel_talk_20017_01", 0, 21, "", 20172, "", 1201720009, 0, "", "");
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (106611, "あ、相変わらずのケンカバカですね……\nあたしはこんな面倒な仕事放り出して、\nさっさとランドソルに帰りてーですよ。", 1, 11, 0, 20172, 1, 1201720010, 10, 0, 0);
