INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("vo_travel_talk", "vo_travel_talk_20018_02", 0, 21, "", 20182, "", 1201820011, 0, "", "");
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (118011, "……それに、手ぶらで帰ったとなると\n秘書にまた小言を言われそうですし。\nあの子がグゥの音も出なくなるくらい\n稼いで稼いで稼ぎますわよ～っ！", 1, 11, 0, 20182, 1, 1201820012, 10, 0, 0);
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (0, "", "", 91, "", 20182, "", 1201820013, "", "", "");
